{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Procainamide, a benzamide with a basic aminoethyl side chain closely analogous to the query, has systemic oral bioavailability of 75% in patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "N-acetylprocainamide, the acetylated benzamide analogue, has absolute oral bioavailability of 87.2% (range 79.2–93.0%) measured by IV/oral stable-isotope study, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Sematilide, another para-substituted benzamide with a basic aminoethyl side chain, has absolute oral bioavailability of 0.46 ± 0.13, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Haloperidol, which shares the 4-chlorophenyl and basic amine features, has absolute oral bioavailability of 0.65 ± 0.14 in men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Loperamide has very low absolute oral bioavailability (0.3%) attributed to P-gp efflux and first-pass metabolism, but its large lipophilic structure and transporter liability are not shared by the query, so this contradictory evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, moderately lipophilic 4-chlorobenzamide with a morpholinoethyl side chain. Multiple close benzamide analogues (procainamide, N-acetylprocainamide, sematilide) show absolute oral bioavailability well above 20%, and haloperidol also supports high F. The only low-F analogue, loperamide, is structurally dissimilar and its low bioavailability is driven by P-gp efflux and extensive first-pass metabolism not expected for this small, largely neutral molecule. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself.",
    "No direct data on first-pass metabolism or P-gp efflux liability for the query.",
    "The low-F loperamide evidence highlights transporter-mediated uncertainty, but its structural features are not representative of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

